const round=n=>Math.round(n*100)/100;
export function makeFixture(t){let prev=t.closes[0]-.10;const bars=t.closes.map((c,i)=>{const o=i?prev:prev,bar={open:round(o),high:round(Math.max(o,c)+.04),low:round(Math.min(o,c)-.04),close:c,volume:Math.round(600+Math.abs(c-o)*2600+(i%3)*120)};prev=c;return bar});let pv=0,v=0;const line=t.indicator?bars.map((b,i)=>{pv+=(b.high+b.low+b.close)/3*b.volume;v+=b.volume;return t.indicator==='vwap'?pv/v:bars.slice(Math.max(0,i-2),i+1).reduce((n,x)=>n+x.close,0)/Math.min(i+1,3)}):null;return {bars,line,lineLabel:t.indicator==='vwap'?'Synthetic VWAP':t.indicator==='ma'?'3-bar SMA':null,timeframe:t.id==='five-minute'?'5 minutes':'1 minute',synthetic:true,cutoff:bars.length,annotations:[{start:Math.floor(bars.length*.55),end:bars.length-1,text:t.explanation}]}}
const makeOptions=arr=>arr.slice(1,4).map((text,i)=>({id:'o'+i,text,explanation:arr[4+i]}));
export const chartQuestions=patternTopics.flatMap((t,i)=>[t.recognition,t.decision].map((a,j)=>({id:`cp-${t.id}-${j+1}`,topic:t.id,difficulty:j?'Intermediate':'Beginner',source:t.source,prompt:a[0],assumptions:'Original synthetic stock illustration; no historical data or forecast. '+(t.id==='opening-range'?'Bars 1–6 define the first six regular-session minutes.':t.id==='gap-go'?'Bar 6 starts the regular session; prior close $9.50.':t.id==='red-green'?'Prior close $10.00 is the comparison reference.':t.id==='gap-down'||t.id==='gap-fade'?'Prior close $10.00 is supplied separately.':t.id==='halt'?'A fictional trading pause is stipulated after bar 6.':'Use only the displayed bars; no later outcome is supplied.'),type:'choice',options:makeOptions(a),correct:'o0',explanation:a[4],hint:'Compare the specified reference with what the chart actually shows; avoid assuming the next move.',relatedLesson:'pattern:'+t.id,chart:makeFixture(t),interpretation:'Question rules, prices and decisions are original educational interpretations, not verbatim source instructions.'})));
// Region tasks use neutral A/B/C time bands and the same keyboard-operable choices.
for(const [topic,index,correct,prompt,why] of [['bull-flag',0,0,'Select the time band containing closes $10.00, $10.30 and $10.80.','The three specified early closes are in region A.'],['bear-flag',0,0,'Select the band containing the first three bars of the initial decline.','The first three bars lie in region A, before the later bounce.'],['abcd-stall',0,2,'Select the band where the continuation loses momentum below the earlier high.','The right edge stalls after the earlier swings.'],['first-pullback',0,2,'Select the band containing the first pullback after the sharp rise.','The small decline follows the impulse in the final band.'],['micro',0,1,'Select the band containing the small setback between the closes 11.25 and 11.20.','That one-candle setback is in the middle band.'],['head-shoulders',0,1,'Select the band containing the highest central peak.','The tallest middle swing lies in the middle band.'],['inverse',0,1,'Select the band containing the deepest central trough.','The central low lies in the middle band.'],['bull-trap',0,2,'Select the band where price falls back below the earlier ceiling.','The failed push and retreat occur near the right edge.']]){const q=chartQuestions.find(q=>q.topic===topic&&q.id.endsWith('-1'));q.type='region';q.prompt=prompt;q.options=['A: early bars','B: middle bars','C: latest bars'].map((text,i)=>({id:'r'+i,text,explanation:i===correct?why:'This band does not contain the specified feature; compare its bar numbers with the highlighted answer.'}));q.correct='r'+correct;q.explanation=why;q.regionCorrect=correct;q.chart.highlightRegion=correct;}
const calculations=[
['risk-share','bull-flag','Entry $10.20, planned stop $9.90. What is planned risk per share (USD)?',.30,.005,'10.20 − 9.90 = $0.30. A stop price is not an assured fill.'],
['reward-share','flat-top','Entry $10.20, hypothetical target $10.80. What is potential reward per share (USD)?',.60,.005,'10.80 − 10.20 = $0.60; target attainment is uncertain.'],
['rr','first-pullback','Entry $10.20, stop $9.90, target $10.80. Reward divided by risk?',2,.01,'0.60 / 0.30 = 2. This ratio ignores slippage and fees.'],
['sizing','micro','A fictional $60 loss budget and $0.30 planned risk/share permit how many whole shares?',200,0,'60 / 0.30 = 200 shares before execution effects.'],
['chasing','parabolic','Same stop $14: buying at $17.50 instead of $15 adds how much planned risk/share?',2.5,.005,'3.50 − 1.00 = $2.50 additional downside per share.'],
['short-risk','bear-flag','Hypothetical short entry $10, stop $10.40. Planned risk/share (USD)?',.4,.005,'10.40 − 10.00 = $0.40. Actual short losses can exceed a planned stop.'],
['position-risk','trend-shift','150 shares × $0.20 planned risk/share: total planned dollar risk?',30,.005,'150 × 0.20 = $30, excluding slippage and fees.'],
['half-dollar','whole-half','Next half-dollar level strictly above $9.72?',10,.005,'$10.00 follows $9.50. Round levels do not ensure support or resistance.'],
['gap-size','gap-go','Prior close $9.50, first regular-session price $10.80. Upward gap in USD/share?',1.3,.005,'10.80 − 9.50 = $1.30. This is supplied fictional arithmetic.'],
['remaining-gap','gap-fade','Prior close $10, current $10.20. Dollars/share still above prior close?',.2,.005,'10.20 − 10.00 = $0.20. A partial fade need not finish.'],
['drawdown','bull-trap','A fictional account drops from $1,000 to $900. Loss as a percentage of the original equity?',10,.01,'100 / 1000 × 100 = 10%. A later recovery uses a different denominator.'],
['volume','vwap-break','Illustrative volume rises from 1,000 to 2,500 shares. New volume divided by old volume?',2.5,.01,'2500 / 1000 = 2.5 times. Volume alone does not guarantee direction.']
];
chartQuestions.push(...calculations.map(([id,topic,prompt,answer,tolerance,explanation])=>({id:'cp-calc-'+id,topic,difficulty:'Intermediate',source:patternTopics.find(t=>t.id===topic).source,prompt,type:'numeric',answer,tolerance,explanation,assumptions:'All supplied numbers are hypothetical and original. Arithmetic exercise, not a claim about the source trade.',hint:'Write the units and operation before calculating.',relatedLesson:'pattern:'+topic,interpretation:'Original numerical application of the concept, not source prices.'})));
for(const q of chartQuestions.filter(q=>q.chart)){const t=q.topic,focus={ 'flat-top':[2,3,5,7], 'flat-bottom':[2,3,5,7], 'ma-pullback':[4,5,6,7,8], 'ma-pop-short':[4,5,6,7], 'five-minute':[5,6], 'one-minute':[9,10,11], 'bull-trap':[5,6,7,8,9], 'gap-go':[4,5,6], 'red-green':[2,3,4,5,6], 'vwap-pullback':[4,5,6,7,8], 'vwap-fade':[4,5,6,7,8,9], 'vwap-break':[4,5,6,7,8,9],parabolic:[6,7,8,9], 'gap-down':[2,3,4,8,9], 'gap-fade':[2,3,4,8,9], 'opening-range':[0,1,2,3,4,5]};q.chart.focusBars=focus[t]||q.chart.bars.map((_,i)=>i)}
export const patternCards=patternTopics.map(t=>({id:'pattern:'+t.id,topic:t.id,title:t.title,explanation:t.explanation,source:t.source,chart:makeFixture(t)}));


